def common_prefix(strings, n):
    if n <= 0:
        return ""
    # consider the first n strings
    # find the minimum length among them to avoid index errors
    min_len = min(len(s) for s in strings[:n])
    prefix = []
    for i in range(min_len):
        char = strings[0][i]
        # check if all n strings have the same character at position i
        all_match = True
        for s in strings[:n]:
            if s[i] != char:
                all_match = False
                break
        if not all_match:
            break
        prefix.append(char)
    return ''.join(prefix)
