def cal_sum(n):
    """Return the sum of Perrin numbers from P(0) to P(n) inclusive."""
    if n < 0:
        return 0
    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3) for n>2
    p = [3, 0, 2]
    if n < 3:
        return sum(p[:n+1])
    for i in range(3, n + 1):
        p.append(p[i - 2] + p[i - 3])
    return sum(p[:n + 1])
